1	/**
2	 * Orchestrator main entry point.
3	 *
4	 * Lifecycle:
5	 *   bootstrap (once) → polling loop:
6	 *     pull workspaces → eligibility → claim → briefing → adapter.run →
7	 *     side-effects → sleep → repeat
8	 *
9	 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
10	 *   0   → single-shot mode: one cycle then exit
11	 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
12	 *
13	 * Exit codes:
14	 *   0  normal exit
15	 *   2  agent.yaml invalid
16	 *   3  git clone/pull failed (bootstrap only)
17	 *   4  unexpected fatal error
18	 */
19	
20	import { existsSync, readFileSync, writeFileSync } from "node:fs";
21	import { join } from "node:path";
22	import { tmpdir } from "node:os";
23	import { execSync } from "node:child_process";
24	import { randomUUID } from "node:crypto";
25	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
26	import { runBootstrap } from "./bootstrap/bootstrap.js";
27	import { resolveSSHKey } from "./resolve-ssh-key.js";
28	import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "./paths.js";
29	import { findEligibleTasks } from "./eligibility/match.js";
30	import { claimTask } from "./claim/claim-task.js";
31	import { openWorkspacePr } from "./claim/open-workspace-pr.js";
32	import type { Task, TaskLogEntry } from "./types/task.js";
33	import { generateBriefing } from "./briefing/agent-context.js";
34	import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
35	import { resolveModel } from "./config/resolve-model-policy.js";
36	import { parseModelOverrides } from "./config/parse-model-overrides.js";
37	import {
38	  resolveRepoLocalPath,
39	  resolveRepoBaseBranch,
40	  resolveRepoGitUrl,
41	  loadWorkspaceModelPolicy,
42	  parseManagementRepoCoords,
43	} from "./config/workspace-config.js";
44	import { pullWorkspaces } from "./poll/pull-workspaces.js";
45	import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
46	import { runReapLoop } from "./poll/reap-loop.js";
47	import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
48	import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
49	import { handleDraftReviews } from "./pr-response/dispatch-draft-review.js";
50	import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
51	import type { ExecutorPortInput } from "@workflow/runtime-abi";
52	import { buildGitEnv } from "./git-env.js";
53	import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
54	import { createLocalSubprocessProfile } from "./profiles/local-subprocess.js";
55	import type { RuntimePorts } from "./runtime-ports.js";
56	import { SubProcessAdapterW2 } from "./adapters/executor/subprocess.js";
57	
58	// ── Helpers ───────────────────────────────────────────────────────────────────
59	
60	function requireEnv(name: string): string {
61	  const val = process.env[name];
62	  if (!val) throw new Error(`Required environment variable ${name} is not set`);
63	  return val;
64	}
65	
66	function extractRepoName(url: string): string {
67	  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
68	  return match?.[1] ?? url;
69	}
70	
71	/** Emit a structured JSON event via the profile's EventEmitterPort. */
72	function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
73	  return (event: Record<string, unknown>) => {
74	    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
75	    ports.emitter.emit(type ?? "event", data);
76	  };
77	}
78	
79	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
80	  const task = parseYaml(
81	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
82	  ) as { repo: string };
83	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
84	  return task.repo;
85	}
86	
87	interface TaskContext {
88	  taskRepoRoot: string;
89	  taskRepoUrl: string;
90	  taskBaseBranch: string;
91	  implementationModel: string;
92	}
93	
94	function resolveTaskContext(
95	  workspaceLocalPath: string,
96	  featureId: string,
97	  task: Task,
98	): TaskContext {
99	  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
100	  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
101	  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
102	  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
103	
104	  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
105	  let taskModelOverrides = {};
106	  try {
107	    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
108	  } catch { /* non-fatal */ }
109	
110	  const implementationModel = resolveModel(
111	    workspaceModelPolicy,
112	    taskModelOverrides,
113	    "implementation",
114	    task.id,
115	  );
116	
117	  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
118	}
119	
120	/**
121	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
122	 * Commits and pushes to the task branch. Throws on error.
123	 */
124	function writeRagPreFlight(
125	  workspaceRoot: string,
126	  featureId: string,
127	  taskId: string,
128	  taskBranch: string,
129	  gitAuthorEmail: string,
130	  gitAuthorName: string,
131	  sshKeyPath: string | undefined,
132	  ragPreFlight: { query: string; injected: boolean; summary: string },
133	): void {
134	  const now = new Date().toISOString();
135	  const entry: TaskLogEntry = {
136	    action: "rag_pre_flight",
137	    by: gitAuthorEmail,
138	    at: now,
139	    rag_context_injected: ragPreFlight.injected,
140	    rag_summary: ragPreFlight.summary,
141	    rag_query: ragPreFlight.query,
142	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
143	  };
144	
145	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
146	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
147	  task.log.push(entry);
148	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
149	
150	  const relPath = taskYamlRelPath(featureId, taskId);
151	  const gitOpts = {
152	    cwd: workspaceRoot,
153	    encoding: "utf-8" as const,
154	    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
155	    timeout: 30_000,
156	    stdio: "pipe" as const,
157	  };
158	  execSync(`git add "${relPath}"`, gitOpts);
159	  execSync(
160	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
161	    gitOpts,
162	  );
163	  execSync(`git push origin "${taskBranch}"`, gitOpts);
164	}
165	
166	// ── Main ──────────────────────────────────────────────────────────────────────
167	
168	async function main(): Promise<number> {
169	  let agentYamlPath: string;
170	  let workflowLocalPath: string;
171	  let workspacesRoot: string;
172	  let gitAuthorEmail: string;
173	
174	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
175	  const bootstrapEmit = (event: Record<string, unknown>) => {
176	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
177	  };
178	
179	  try {
180	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
181	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
182	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
183	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
184	  } catch (e) {
185	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
186	    return 4;
187	  }
188	
189	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
190	
191	  const sshResolution = resolveSSHKey(process.env);
192	  const sshKeyPath = sshResolution.sshKeyPath;
193	
194	  // ── Create the local-subprocess profile ──────────────────────────────────────
195	  // The profile bundles all port adapters for the current deployment topology.
196	  // Switching profiles at startup is how new infra is added without core changes.
197	  const ports = createLocalSubprocessProfile({
198	    gitAuthorEmail,
199	    gitAuthorName,
200	    sshKeyPath,
201	  });
202	
203	  // T3: Start the embedded broker's HTTP receiver so runners can POST callbacks.
204	  // The broker is dormant (not yet wired into claims) until T5/T6 ship, but the
205	  // port must be bound at startup so the port file is present for spawn code.
206	  const brokerPort = await ports.broker.start();
207	
208	  const emit = makeEmit(ports);
209	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
210	
211	  if (sshResolution.warned) {
212	    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
213	  }
214	
215	  const bootstrapResult = await runBootstrap({
216	    agentYamlPath,
217	    workflowLocalPath,
218	    workflowUrl: process.env.WORKFLOW_URL,
219	    workspacesRoot,
220	    sshKeyPath,
221	  });
222	
223	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
224	
225	  const config = bootstrapResult.config!;
226	  const githubToken = process.env.GITHUB_TOKEN ?? "";
227	  if (!githubToken) emit({ type: "warn_no_github_token" });
228	
229	  let lastPrPollAt: number | null = null;
230	
231	  async function runOneCycle(): Promise<CycleOutcome> {
232	    const pullResults = pullWorkspaces({
233	      watchUrls: config.watches,
234	      sshKeyPath,
235	      workspacesRoot,
236	      workflowUrl: process.env.WORKFLOW_URL,
237	      workflowLocalPath,
238	      emit,
239	    });
240	
241	    const haltedUrls = new Set(
242	      pullResults
243	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
244	        .map((r) => r.url),
245	    );
246	
247	    let outcome: CycleOutcome = "idle";
248	    const pulledWorkspaceRoots: string[] = [];
249	
250	    outerLoop:
251	    for (const watchUrl of config.watches) {
252	      if (haltedUrls.has(watchUrl)) continue;
253	
254	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
255	      pulledWorkspaceRoots.push(workspaceLocalPath);
256	
257	      if (!existsSync(workspaceLocalPath)) {
258	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
259	        continue;
260	      }
261	
262	      let eligibleTasks;
263	      try {
264	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
265	      } catch (e) {
266	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
267	        continue;
268	      }
269	
270	      if (eligibleTasks.length === 0) {
271	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
272	        continue;
273	      }
274	
275	      for (const { task, featureId } of eligibleTasks) {
276	        const claimResult = await claimTask({
277	          workspaceRoot: workspaceLocalPath,
278	          taskId: task.id,
279	          featureId,
280	          gitAuthorEmail,
281	          gitAuthorName,
282	          sshKeyPath,
283	          jitterMaxSeconds: config.jitter_max_seconds,
284	        });
285	
286	        const taskBranch = taskBranchName(featureId, task.id);
287	
288	        if (!claimResult.won) {
289	          if (claimResult.reason !== "branch_blocked_recovery") {
290	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
291	            continue;
292	          }
293	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
294	        } else {
295	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
296	        }
297	
298	        // ── Open management-repo PR ───────────────────────────────────────────
299	        if (githubToken) {
300	          try {
301	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
302	            await openWorkspacePr({
303	              workspaceRoot: workspaceLocalPath,
304	              featureId,
305	              taskId: task.id,
306	              branch: taskBranch,
307	              baseBranch: mgmtCoords.baseBranch,
308	              githubToken,
309	              repoOwner: mgmtCoords.owner,
310	              repoName: mgmtCoords.repo,
311	              gitAuthorEmail,
312	              gitAuthorName,
313	              sshKeyPath,
314	            });
315	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
316	          } catch (e) {
317	            const stderr = (e as { stderr?: Buffer | string }).stderr;
318	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
319	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
320	          }
321	        }
322	
323	        // ── Resolve model + task repo ────────────────────────────────────────
324	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
325	          resolveTaskContext(workspaceLocalPath, featureId, task);
326	
327	        // ── RAG pre-flight ───────────────────────────────────────────────────
328	        const mcpRagUrl = process.env.MCP_RAG_URL;
329	        const workspaceYaml = parseYaml(
330	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
331	        ) as { workspace_id: string };
332	        const ragQuery = `${task.title} ${featureId}`;
333	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
334	
335	        try {
336	          writeRagPreFlight(
337	            workspaceLocalPath,
338	            featureId,
339	            task.id,
340	            taskBranch,
341	            gitAuthorEmail,
342	            gitAuthorName,
343	            sshKeyPath,
344	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
345	          );
346	        } catch (e) {
347	          const details = String(e);
348	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
349	          mutateTaskYaml({
350	            workspaceRoot: workspaceLocalPath,
351	            featureId,
352	            taskId: task.id,
353	            taskBranch,
354	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
355	            gitAuthorEmail,
356	            gitAuthorName,
357	            sshKeyPath,
358	          });
359	          continue;
360	        }
361	
362	        // ── Generate briefing ────────────────────────────────────────────────
363	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
364	        const baseContext = generateBriefing({
365	          taskId: task.id,
366	          featureId,
367	          taskTitle: task.title,
368	          taskBranch,
369	          taskRepo: task.repo,
370	          taskRepoRoot,
371	          workspaceRoot: workspaceLocalPath,
372	          gitAuthorEmail,
373	          gitAuthorName,
374	          implementationModel,
375	          resultPath,
376	        });
377	        const briefingContent = ragPreFlight.block
378	          ? `${baseContext}\n\n${ragPreFlight.block}`
379	          : baseContext;
380	
381	        // ── Write briefing via BriefingTransportPort ─────────────────────────
382	        // Use taskId as the briefing handle so the file path matches the
383	        // existing briefing-{taskId}/briefing.md convention.
384	        const briefingPath = await ports.briefing.put(task.id, briefingContent);
385	
386	        // ── Build ExecutorPortInput ──────────────────────────────────────────
387	        const nonce = randomUUID();
388	        const callbackUrl = ports.broker.getCallbackUrl() ?? "";
389	
390	        const execInput: ExecutorPortInput = {
391	          taskId: task.id,
392	          featureId,
393	          workspaceId: workspaceYaml.workspace_id,
394	          taskRepoUrl,
395	          taskRepoBranch: taskBranch,
396	          taskRepoPath: taskRepoRoot,
397	          briefingPath,
398	          resultPath,
399	          budgetTokens: config.budget.max_tokens_per_task,
400	          sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
401	          githubToken,
402	          callbackUrl,
403	          nonce,
404	        };
405	
406	        // ── Submit executor (async — T6) ─────────────────────────────────────
407	        // extraEnv is per-task so a fresh SubProcessAdapterW2 is created here;
408	        // other ports (emitter, scheduler, etc.) are reused from the profile.
409	        const perTaskExecutor = new SubProcessAdapterW2({
410	          broker: ports.broker,
411	          extraEnv: {
412	            WORKSPACE_ROOT: workspaceLocalPath,
413	            TASK_BRANCH: taskBranch,
414	            GIT_AUTHOR_EMAIL: gitAuthorEmail,
415	            GIT_AUTHOR_NAME: gitAuthorName,
416	            WORKFLOW_LOCAL_PATH: workflowLocalPath,
417	            MAX_TURNS: String(config.budget.max_iterations),
418	            LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
419	            ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
420	            ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
421	              ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
422	              : {}),
423	          },
424	        });
425	
426	        const execHandle = await perTaskExecutor.submit(execInput);
427	
428	        // Persist handle to task YAML for broker crash-recovery reconciliation.
429	        try {
430	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
431	        } catch (e) {
432	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
433	        }
434	
435	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
436	        outcome = "ran_task";
437	        break outerLoop;
438	      }
439	    }
440	
441	    // ── In-review PR poll ─────────────────────────────────────────────────────
442	    if (githubToken) {
443	      const prPollIntervalMs =
444	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
445	      const now = Date.now();
446	
447	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
448	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
449	        try {
450	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
451	            workspaceRoots: pulledWorkspaceRoots,
452	            githubToken,
453	            emit,
454	          });
455	
456	          for (const wsRoot of pulledWorkspaceRoots) {
457	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
458	            if (wsResults.some((r) => r.mergeable === false)) {
459	              await handleMergeConflicts({
460	                prResults: wsResults,
461	                workspaceRoot: wsRoot,
462	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
463	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
464	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
465	                gitAuthorEmail,
466	                gitAuthorName,
467	                sshKeyPath,
468	                emit,
469	              });
470	            }
471	          }
472	
473	          for (const wsRoot of pulledWorkspaceRoots) {
474	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
475	            if (wsResults.some((r) => r.hasOpenComments === true)) {
476	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
477	              await handleDraftReviews({
478	                prResults: wsResults,
479	                workspaceRoot: wsRoot,
480	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
481	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
482	                resolveImplementationModel: (fId, tId) => {
483	                  try {
484	                    const tMdPath = join(wsRoot, "docs", "features", fId, "tasks.md");
485	                    const overrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), tId);
486	                    return resolveModel(wsModelPolicy, overrides, "implementation", tId);
487	                  } catch {
488	                    return resolveModel(wsModelPolicy, {}, "implementation", tId);
489	                  }
490	                },
491	                gitAuthorEmail,
492	                gitAuthorName,
493	                sshKeyPath,
494	                workflowLocalPath,
495	                maxTurns: config.budget.max_iterations,
496	                maxTokens: config.budget.max_tokens_per_task,
497	                logSinkEnabled: config.log_sink.enabled,
498	                workspaceId: (() => {
499	                  try {
500	                    return (parseYaml(readFileSync(workspaceYamlPath(wsRoot), "utf-8")) as { workspace_id: string }).workspace_id ?? "";
501	                  } catch { return ""; }
502	                })(),
503	                githubToken,
504	                resolveImplRepoUrl: (repoId) => resolveRepoGitUrl(wsRoot, repoId),
505	                broker: ports.broker,
506	                callbackUrl: ports.broker.getCallbackUrl() ?? "",
507	                emit,
508	              });
509	            }
510	          }
511	
512	          for (const wsRoot of pulledWorkspaceRoots) {
513	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
514	            if (wsResults.some((r) => r.merged === true)) {
515	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
516	              await handleMergedPrs({
517	                prResults: wsResults,
518	                workspaceRoot: wsRoot,
519	                mgmtRepoOwner: mgmtCoords.owner,
520	                mgmtRepoName: mgmtCoords.repo,
521	                mgmtBaseBranch: mgmtCoords.baseBranch,
522	                githubToken,
523	                gitAuthorEmail,
524	                gitAuthorName,
525	                sshKeyPath,
526	                emit,
527	              });
528	            }
529	          }
530	
531	          for (const wsRoot of pulledWorkspaceRoots) {
532	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
533	            if (wsRecoveries.length > 0) {
534	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
535	              await handleWorkspacePrRecoveries({
536	                recoveries: wsRecoveries,
537	                mgmtRepoOwner: mgmtCoords.owner,
538	                mgmtRepoName: mgmtCoords.repo,
539	                mgmtBaseBranch: mgmtCoords.baseBranch,
540	                githubToken,
541	                gitAuthorEmail,
542	                gitAuthorName,
543	                sshKeyPath,
544	                emit,
545	              });
546	            }
547	          }
548	        } catch (e) {
549	          emit({ type: "in_review_poll_error", details: String(e) });
550	        }
551	      }
552	    }
553	
554	    // ── Shared reap loop ──────────────────────────────────────────────────────
555	    // Drain completions posted by in-flight executors this cycle (and any
556	    // leftovers from previous cycles). Routes by handle.kind → dispatcher.
557	    try {
558	      const reapResult = await runReapLoop({
559	        broker: ports.broker,
560	        workspaceRoots: pulledWorkspaceRoots,
561	        gitAuthorEmail,
562	        gitAuthorName,
563	        sshKeyPath,
564	        githubToken,
565	        emit,
566	      });
567	      if (reapResult.dispatched > 0) {
568	        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
569	        if (outcome === "idle") outcome = "ran_task";
570	      }
571	    } catch (e) {
572	      emit({ type: "reap_loop_error", details: String(e) });
573	    }
574	
575	    return outcome;
576	  }
577	
578	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
579	  return 0;
580	}
581	
582	main()
583	  .then((code) => process.exit(code))
584	  .catch((e) => {
585	    try {
586	      console.log(JSON.stringify({
587	        type: "fatal_error",
588	        details: (e as Error).message ?? String(e),
589	        at: new Date().toISOString(),
590	      }));
591	    } catch { /* last resort */ }
592	    process.exit(4);
593	  });
