1	/**
2	 * Shared reap loop — drains completed executions from the broker,
3	 * routes by handle.kind, and dispatches side-effects.
4	 *
5	 * Called once per orchestrator cycle after the claim and review-fix
6	 * concerns have submitted their work. Any orchestrator can drain any
7	 * completion — dispatch is opportunistic, not pinned to the submitter.
8	 *
9	 * Routing:
10	 *   kind=impl       → dispatchExecutorResult (task YAML mutation)
11	 *   kind=review-fix → emit review_dispatch_complete event
12	 *
13	 * Error handling: individual dispatch errors are emitted as events and
14	 * the item is nacked (returned to the queue). Non-throwing.
15	 */
16	
17	import { existsSync } from "node:fs";
18	import type { CompletionBrokerPort } from "@workflow/runtime-abi";
19	import { dispatchExecutorResult } from "../side-effects/dispatch.js";
20	import { readTask } from "../utils/task-yaml-io.js";
21	import { taskYamlAbsPath } from "../paths.js";
22	import {
23	  resolveRepoGitUrl,
24	  resolveRepoBaseBranch,
25	} from "../config/workspace-config.js";
26	
27	// ── Types ─────────────────────────────────────────────────────────────────────
28	
29	export interface ReapLoopOptions {
30	  broker: CompletionBrokerPort;
31	  /** All workspace roots pulled this cycle — used to locate the task YAML. */
32	  workspaceRoots: string[];
33	  /** Visibility-lock duration for peek-and-lock. Default: 30 000 ms. */
34	  lockMs?: number;
35	  /** Max completions to drain per call. Default: 10. */
36	  max?: number;
37	  gitAuthorEmail: string;
38	  gitAuthorName?: string;
39	  sshKeyPath?: string;
40	  githubToken: string;
41	  emit: (event: Record<string, unknown>) => void;
42	}
43	
44	export interface ReapLoopResult {
45	  /** Completions successfully dispatched and acked. */
46	  dispatched: number;
47	  /** Completions that failed to dispatch (nacked, will be retried). */
48	  failed: number;
49	}
50	
51	// ── Helpers ───────────────────────────────────────────────────────────────────
52	
53	/**
54	 * Find the workspace root whose tasks directory contains the given task YAML.
55	 * Returns undefined if the task is not found in any pulled workspace.
56	 */
57	function findWorkspaceRoot(
58	  workspaceRoots: string[],
59	  featureId: string,
60	  taskId: string,
61	): string | undefined {
62	  for (const root of workspaceRoots) {
63	    try {
64	      if (existsSync(taskYamlAbsPath(root, featureId, taskId))) return root;
65	    } catch {
66	      // ignore fs errors
67	    }
68	  }
69	  return undefined;
70	}
71	
72	// ── Public API ────────────────────────────────────────────────────────────────
73	
