124	   * has been opened.
125	   */
126	  conflict_state?: ConflictState | null;
127	  /**
128	   * Append-only log of rebase operations performed against this task's
129	   * implementation branch.  Each entry is written atomically with the
130	   * associated management-repo push so the log is always consistent with the
131	   * branch state.
132	   */
133	  rebase_log?: RebaseLogEntry[];
134	}
