135	
136	export async function dispatchOneReview(
137	  opts: DispatchOneReviewOptions,
138	): Promise<DraftReviewOutcome> {
139	  const {
140	    workspaceRoot,
141	    featureId,
142	    taskId,
143	    taskBranch,
144	    implRepoRoot,
145	    implRepoUrl,
146	    gitAuthorEmail,
147	    gitAuthorName = gitAuthorEmail,
148	    sshKeyPath,
149	    workflowLocalPath,
150	    maxTurns,
151	    maxTokens,
152	    logSinkEnabled,
153	    implementationModel,
154	    workspaceId,
155	    githubToken,
156	    broker,
157	    callbackUrl,
158	    emit,
159	  } = opts;
160	
161	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
162	  const now = new Date().toISOString();
163	
164	  // ── 1. Checkout and reset task branch in management repo ──────────────────────
165	  try {
166	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
167	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
168	    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
169	  } catch (e) {
170	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
171	    return "claim_lost";
172	  }
173	
174	  // ── 2. Read task and guard against duplicate claims ───────────────────────────
175	  let task: Task;
176	  try {
177	    task = readTask(workspaceRoot, featureId, taskId);
178	  } catch (e) {
179	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
180	    return "claim_lost";
181	  }
182	
183	  const lastEntry = task.log[task.log.length - 1];
184	  if (lastEntry?.action === "review_started") {
185	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is review_started" });
186	    return "claim_lost";
187	  }
188	
189	  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
190	  const MAX_REVIEW_CYCLES = 3;
191	  let consecutiveReviewCycles = 0;
192	  for (let i = task.log.length - 1; i >= 0; i--) {
193	    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
194	    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
195	  }
196	  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
197	    emit({ type: "review_loop_detected", task_id: taskId, feature_id: featureId });
198	    return "claim_lost";
199	  }
200	
201	  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
202	  task.log.push({ action: "review_started", by: gitAuthorEmail, at: now, note: "Review dispatch claimed." });
203	  task.execution.last_updated_by = gitAuthorEmail;
204	  task.execution.last_updated_at = now;
205	  writeTask(workspaceRoot, featureId, task);
206	
207	  const relPath = taskYamlRelPath(featureId, taskId);
208	  try {
209	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
210	    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`, { env, stdio: "pipe" });
211	  } catch (e) {
212	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
213	    return "claim_lost";
214	  }
215	
216	  const claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
217	    env, encoding: "utf-8",
218	  });
219	  if (claimPush.status !== 0) {
220	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
221	    return "claim_lost";
222	  }
223	
224	  emit({ type: "review_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr.url });
225	
226	  // ── 4. Build review briefing and submit executor (async — T6) ────────────────
227	  const reviewBriefing = generateReviewBriefing({
228	    taskId,
229	    featureId,
230	    taskTitle: task.title,
231	    taskBranch,
232	    taskRepo: task.repo,
233	    taskRepoRoot: implRepoRoot,
234	    workspaceRoot,
235	    prUrl: task.pr.url,
236	    gitAuthorEmail,
237	    gitAuthorName,
238	    implementationModel,
239	  });
240	
241	  const { briefingPath } = writeBriefing({ taskId, briefingContent: reviewBriefing });
242	
243	  const resultPath = join(tmpdir(), `review-result-${taskId}.json`);
244	  const nonce = randomUUID();
245	
246	  const input: ExecutorPortInput = {
247	    taskId,
248	    featureId,
249	    workspaceId,
250	    taskRepoUrl: implRepoUrl,
251	    taskRepoBranch: taskBranch,
252	    taskRepoPath: implRepoRoot,
253	    briefingPath,
254	    resultPath,
255	    budgetTokens: maxTokens,
256	    sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
257	    githubToken,
258	    callbackUrl,
259	    nonce,
260	  };
261	
262	  const reviewAdapter = new SubProcessAdapterW2({
263	    broker,
264	    extraEnv: {
265	      WORKSPACE_ROOT: workspaceRoot,
266	      TASK_BRANCH: taskBranch,
267	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
268	      GIT_AUTHOR_NAME: gitAuthorName,
269	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
270	      MAX_TURNS: String(maxTurns),
271	      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
272	    },
273	  });
274	
275	  const handle = await reviewAdapter.submit(input);
276	
277	  emit({
278	    type: "review_submitted",
279	    task_id: taskId,
280	    feature_id: featureId,
281	    handle,
282	  });
283	
284	  return "dispatched";
285	}
