287	export async function handleDraftReviews(
288	  opts: HandleDraftReviewsOptions,
289	): Promise<void> {
290	  const {
291	    prResults,
292	    workspaceRoot,
293	    resolveImplRepoRoot,
294	    resolveImplRepoUrl,
295	    resolveTaskRepoId,
296	    resolveImplementationModel,
297	    gitAuthorEmail,
298	    gitAuthorName,
299	    sshKeyPath,
300	    workflowLocalPath,
301	    maxTurns,
302	    maxTokens,
303	    logSinkEnabled,
304	    workspaceId,
305	    githubToken,
306	    broker,
307	    callbackUrl,
308	    emit,
309	  } = opts;
310	
311	  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);
312	
313	  for (const result of draftTasks) {
314	    const { taskId, featureId } = result;
315	
316	    let repoId: string;
317	    try {
318	      repoId = resolveTaskRepoId(featureId, taskId);
319	    } catch (e) {
320	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
321	      continue;
322	    }
323	
324	    let implRepoRoot: string;
325	    let implRepoUrl: string;
326	    try {
327	      implRepoRoot = resolveImplRepoRoot(repoId);
328	      implRepoUrl = resolveImplRepoUrl(repoId);
329	    } catch (e) {
330	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
331	      continue;
332	    }
333	
334	    let implementationModel: string;
335	    try {
336	      implementationModel = resolveImplementationModel(featureId, taskId);
337	    } catch (e) {
338	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
339	      continue;
340	    }
341	
342	    const taskBranch = `feature/${featureId}-${taskId}`;
343	
344	    try {
345	      await dispatchOneReview({
346	        workspaceRoot,
347	        featureId,
348	        taskId,
349	        taskBranch,
350	        implRepoRoot,
351	        implRepoUrl,
352	        gitAuthorEmail,
353	        gitAuthorName,
354	        sshKeyPath,
355	        workflowLocalPath,
356	        maxTurns,
357	        maxTokens,
358	        logSinkEnabled,
359	        implementationModel,
360	        workspaceId,
361	        githubToken,
362	        broker,
363	        callbackUrl,
364	        emit,
365	      });
366	    } catch (e) {
367	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
368	    }
369	  }
370	}
