/**
 * T4: Draft-state comment resolution dispatch.
 *
 * When T2 reports `hasOpenComments: true` for an `in_review` task, this handler:
 *
 *   1. Claims the review work by appending a `review_started` log entry to
 *      the task YAML on the management-repo feature branch and pushing.
 *      First-push-wins: if the push is rejected, another agent claimed first.
 *
 *   2. Generates a review briefing that instructs Claude to execute the
 *      `respond-to-review` skill.
 *
 *   3. Invokes the Claude executor via SubProcessAdapter with that briefing.
 */

import { execSync, spawnSync } from "node:child_process";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { randomUUID } from "node:crypto";
import type { Task } from "../types/task.js";
import type { PrStatusResult } from "../poll/check-in-review-prs.js";
import { buildGitEnv } from "../git-env.js";
import { SubProcessAdapterW2 } from "../adapters/executor/subprocess.js";
import type { ExecutorPortInput, CompletionBrokerPort } from "@workflow/runtime-abi";
import { taskYamlRelPath } from "../paths.js";
import { readTask, writeTask } from "../utils/task-yaml-io.js";
import { writeBriefing } from "../briefing/write-briefing.js";
import { preambleSection, identitySection, taskContextSection, modelSection, joinSections } from "../briefing/briefing-template.js";

// ── Public types ──────────────────────────────────────────────────────────────

export type DraftReviewOutcome =
  | "claim_lost"
  | "dispatched";

export interface DispatchOneReviewOptions {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  implRepoRoot: string;
  /** SSH or HTTPS URL of the implementation repo. */
  implRepoUrl: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  workflowLocalPath: string;
  maxTurns: number;
  maxTokens: number;
  logSinkEnabled: boolean;
  implementationModel: string;
  workspaceId: string;
  githubToken: string;
  /** Completion broker for async submit. */
  broker: CompletionBrokerPort;
  /** Callback URL the runner wrapper will POST to. Pre-computed by caller. */
  callbackUrl: string;
  emit: (event: Record<string, unknown>) => void;
}

export interface HandleDraftReviewsOptions {
  prResults: PrStatusResult[];
  workspaceRoot: string;
  resolveImplRepoRoot: (repoId: string) => string;
  resolveImplRepoUrl: (repoId: string) => string;
  resolveTaskRepoId: (featureId: string, taskId: string) => string;
  resolveImplementationModel: (featureId: string, taskId: string) => string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  workflowLocalPath: string;
  maxTurns: number;
  maxTokens: number;
  logSinkEnabled: boolean;
  workspaceId: string;
  githubToken: string;
  /** Completion broker for async submit. */
  broker: CompletionBrokerPort;
  /** Callback URL the runner wrapper will POST to. */
  callbackUrl: string;
  emit: (event: Record<string, unknown>) => void;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

function generateReviewBriefing(opts: {
  taskId: string;
  featureId: string;
  taskTitle: string;
  taskBranch: string;
  taskRepo: string;
  taskRepoRoot: string;
  workspaceRoot: string;
  prUrl: string;
  gitAuthorEmail: string;
  gitAuthorName: string;
  implementationModel: string;
}): string {
  const {
    taskId, featureId, taskTitle, taskBranch, taskRepo, taskRepoRoot,
    workspaceRoot, prUrl, gitAuthorEmail, gitAuthorName, implementationModel,
  } = opts;

  return joinSections(
    preambleSection(),
    identitySection({ gitAuthorEmail, gitAuthorName }),
    taskContextSection("Your claimed task", {
      taskId, featureId, taskTitle, taskBranch,
      taskRepo, taskRepoRoot, workspaceRoot, prUrl,
    }),
    [
      "## What you must do",
      "",
      "1. Read the following documents in order to understand the task context before reviewing:",
      `   a. \`${workspaceRoot}/docs/features/${featureId}/product-spec.md\` — original user requirements and business constraints`,
      `   b. \`${workspaceRoot}/docs/features/${featureId}/technical-design.md\` — implementation approach and architecture`,
      `   c. \`${workspaceRoot}/docs/features/${featureId}/tasks.md\` under heading \`## ${taskId} — ${taskTitle}\` — specific task scope and subtasks`,
      "2. Run `/respond-to-review` to read and address all open PR review comments,",
      "   then convert the PR from draft back to ready-for-review.",
      "",
      "Complete all steps without stopping or asking for confirmation.",
    ],
    modelSection(implementationModel),
    [
      "## Rules",
      "",
      "- Do not ask clarifying questions.",
      "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
      "- If you are stuck and cannot proceed, stop gracefully without opening new PRs.",
    ],
  );
}

// ── Public API ────────────────────────────────────────────────────────────────

export async function dispatchOneReview(
  opts: DispatchOneReviewOptions,
): Promise<DraftReviewOutcome> {
  const {
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    implRepoRoot,
    implRepoUrl,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    workflowLocalPath,
    maxTurns,
    maxTokens,
    logSinkEnabled,
    implementationModel,
    workspaceId,
    githubToken,
    broker,
    callbackUrl,
    emit,
  } = opts;

  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const now = new Date().toISOString();

  // ── 1. Checkout and reset task branch in management repo ──────────────────────
  try {
    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
  } catch (e) {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
    return "claim_lost";
  }

  // ── 2. Read task and guard against duplicate claims ───────────────────────────
  let task: Task;
  try {
    task = readTask(workspaceRoot, featureId, taskId);
  } catch (e) {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
    return "claim_lost";
  }

  const lastEntry = task.log[task.log.length - 1];
  if (lastEntry?.action === "review_started") {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is review_started" });
    return "claim_lost";
  }

  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
  const MAX_REVIEW_CYCLES = 3;
  let consecutiveReviewCycles = 0;
  for (let i = task.log.length - 1; i >= 0; i--) {
    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
  }
  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
    emit({ type: "review_loop_detected", task_id: taskId, feature_id: featureId });
    return "claim_lost";
  }

  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
  task.log.push({ action: "review_started", by: gitAuthorEmail, at: now, note: "Review dispatch claimed." });
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  writeTask(workspaceRoot, featureId, task);

  const relPath = taskYamlRelPath(featureId, taskId);
  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`, { env, stdio: "pipe" });
  } catch (e) {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
    return "claim_lost";
  }

  const claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env, encoding: "utf-8",
  });
  if (claimPush.status !== 0) {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
    return "claim_lost";
  }

  emit({ type: "review_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr.url });

  // ── 4. Build review briefing and submit executor (async — T6) ────────────────
  const reviewBriefing = generateReviewBriefing({
    taskId,
    featureId,
    taskTitle: task.title,
    taskBranch,
    taskRepo: task.repo,
    taskRepoRoot: implRepoRoot,
    workspaceRoot,
    prUrl: task.pr.url,
    gitAuthorEmail,
    gitAuthorName,
    implementationModel,
  });

  const { briefingPath } = writeBriefing({ taskId, briefingContent: reviewBriefing });

  const resultPath = join(tmpdir(), `review-result-${taskId}.json`);
  const nonce = randomUUID();

  const input: ExecutorPortInput = {
    taskId,
    featureId,
    workspaceId,
    taskRepoUrl: implRepoUrl,
    taskRepoBranch: taskBranch,
    taskRepoPath: implRepoRoot,
    briefingPath,
    resultPath,
    budgetTokens: maxTokens,
    sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
    githubToken,
    callbackUrl,
    nonce,
  };

  const reviewAdapter = new SubProcessAdapterW2({
    broker,
    extraEnv: {
      WORKSPACE_ROOT: workspaceRoot,
      TASK_BRANCH: taskBranch,
      GIT_AUTHOR_EMAIL: gitAuthorEmail,
      GIT_AUTHOR_NAME: gitAuthorName,
      WORKFLOW_LOCAL_PATH: workflowLocalPath,
      MAX_TURNS: String(maxTurns),
      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
    },
  });

  const handle = await reviewAdapter.submit(input);

  emit({
    type: "review_submitted",
    task_id: taskId,
    feature_id: featureId,
    handle,
  });

  return "dispatched";
}

export async function handleDraftReviews(
  opts: HandleDraftReviewsOptions,
): Promise<void> {
  const {
    prResults,
    workspaceRoot,
    resolveImplRepoRoot,
    resolveImplRepoUrl,
    resolveTaskRepoId,
    resolveImplementationModel,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    workflowLocalPath,
    maxTurns,
    maxTokens,
    logSinkEnabled,
    workspaceId,
    githubToken,
    broker,
    callbackUrl,
    emit,
  } = opts;

  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);

  for (const result of draftTasks) {
    const { taskId, featureId } = result;

    let repoId: string;
    try {
      repoId = resolveTaskRepoId(featureId, taskId);
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
      continue;
    }

    let implRepoRoot: string;
    let implRepoUrl: string;
    try {
      implRepoRoot = resolveImplRepoRoot(repoId);
      implRepoUrl = resolveImplRepoUrl(repoId);
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
      continue;
    }

    let implementationModel: string;
    try {
      implementationModel = resolveImplementationModel(featureId, taskId);
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
      continue;
    }

    const taskBranch = `feature/${featureId}-${taskId}`;

    try {
      await dispatchOneReview({
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        implRepoRoot,
        implRepoUrl,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        workflowLocalPath,
        maxTurns,
        maxTokens,
        logSinkEnabled,
        implementationModel,
        workspaceId,
        githubToken,
        broker,
        callbackUrl,
        emit,
      });
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
    }
  }
}

