import type { CompletionBrokerPort } from "./ports.js";
import type {
  ExecutorHandle,
  HandleMetadata,
  ExecutorCompletion,
  ExecutorResult,
  RunnerCallbackPayload,
} from "./types.js";

interface RegistryEntry {
  nonce: string;
  metadata: HandleMetadata;
  registered_at: number;
}

interface QueueItem {
  handle: ExecutorHandle;
  result: ExecutorResult;
  metadata: HandleMetadata;
  locked_until?: number; // unix ms; absent means unlocked
}

/**
 * In-memory CompletionBrokerPort used in hermetic orchestrator-core tests.
 *
 * Implements the full peek-and-lock contract:
 * - register() adds handles to the in-flight registry (validates no duplicate)
 * - postCallback() simulates a runner POSTing its result (validates nonce)
 * - listCompleted() atomically peeks unlocked items and marks them locked
 * - ack() removes the handle from both registry and queue
 * - nack() immediately unlocks a locked item, returning it to the queue
 * - reclaimExpired() resets locks whose visibility timeout has elapsed
 *
 * Call reclaimExpired() manually in tests to simulate the broker sweep,
 * or use the controllable FakeClock (from fake-ports.ts) to advance time.
 */
export class FakeBrokerAdapter implements CompletionBrokerPort {
  private readonly registry = new Map<ExecutorHandle, RegistryEntry>();
  private readonly queue: QueueItem[] = [];
  private readonly _clock: { now(): number };

  constructor(clock?: { now(): number }) {
    this._clock = clock ?? { now: () => Date.now() };
  }

  async register(
    handle: ExecutorHandle,
    nonce: string,
    metadata: HandleMetadata,
  ): Promise<void> {
    if (this.registry.has(handle)) {
      throw new Error(`FakeBrokerAdapter: handle already registered: ${handle}`);
    }
    this.registry.set(handle, {
      nonce,
      metadata,
      registered_at: this._clock.now(),
    });
  }

  async listCompleted(opts?: {
    max?: number;
    lockMs?: number;
  }): Promise<ExecutorCompletion[]> {
    const now = this._clock.now();
    const max = opts?.max ?? 10;
    const lockMs = opts?.lockMs ?? 30_000;

    this.reclaimExpired();

    const results: ExecutorCompletion[] = [];
    for (const item of this.queue) {
      if (results.length >= max) break;
      if (item.locked_until === undefined || item.locked_until <= now) {
        item.locked_until = now + lockMs;
        results.push({
          handle: item.handle,
          result: item.result,
          metadata: item.metadata,
          locked_until: item.locked_until,
        });
      }
    }
    return results;
  }

  async ack(handle: ExecutorHandle): Promise<void> {
    this.registry.delete(handle);
    const idx = this.queue.findIndex((item) => item.handle === handle);
    if (idx !== -1) this.queue.splice(idx, 1);
  }

  async nack(handle: ExecutorHandle): Promise<void> {
    const item = this.queue.find((item) => item.handle === handle);
    if (item) {
      item.locked_until = undefined;
    }
  }

  /**
   * Simulate a runner POSTing its result to the broker's HTTP receiver.
   * Validates the nonce against the in-flight registry, then enqueues
   * the completion. Throws on unknown handle or nonce mismatch.
   */
  postCallback(payload: RunnerCallbackPayload): void {
    const entry = this.registry.get(payload.handle);
    if (!entry) {
      throw new Error(
        `FakeBrokerAdapter: unknown handle in postCallback: ${payload.handle}`,
      );
    }
    if (entry.nonce !== payload.nonce) {
      throw new Error(
        `FakeBrokerAdapter: nonce mismatch for handle ${payload.handle}`,
      );
    }
    this.queue.push({
      handle: payload.handle,
      result: payload.result,
      metadata: entry.metadata,
    });
  }

  /**
   * Reset any queue items whose visibility-timeout lock has expired,
   * returning them to the unlocked pool for the next listCompleted call.
   * The real broker runs this sweep automatically; in tests call it
   * explicitly after advancing the FakeClock past the lock expiry.
   */
  reclaimExpired(): void {
    const now = this._clock.now();
    for (const item of this.queue) {
      if (item.locked_until !== undefined && item.locked_until <= now) {
        item.locked_until = undefined;
      }
    }
  }

  /** Number of handles currently in the in-flight registry. */
  registrySize(): number {
    return this.registry.size;
  }

  /** Total items in the completion queue (locked or unlocked). */
  queueDepth(): number {
    return this.queue.length;
  }

  /** Items currently locked (visibility timeout not yet expired). */
  lockedCount(): number {
    const now = this._clock.now();
    return this.queue.filter(
      (item) => item.locked_until !== undefined && item.locked_until > now,
    ).length;
  }
}

