/**
 * Tests for pr-response/dispatch-draft-review.ts
 *
 * Unit tests only — no real git operations or Claude spawns. `execSync` and
 * `spawnSync` are mocked via vi.mock. SubProcessAdapterW2 is mocked to avoid
 * subprocess spawning. Filesystem operations use real temp directories.
 *
 * T6 changes: dispatchOneReview now uses SubProcessAdapterW2.submit() (async,
 * non-blocking) instead of SubProcessAdapter.run() (blocking). The function
 * emits "review_submitted" (handle submitted) rather than "review_dispatch_complete"
 * (result received). The reap loop emits the completion event when the runner
 * POSTs its result back to the broker.
 *
 * Covers:
 *   1. dispatchOneReview — claim_lost when checkout of task branch fails
 *   2. dispatchOneReview — claim_lost when task log already has review_started
 *   3. dispatchOneReview — claim_lost when push of claim commit is rejected
 *   4. dispatchOneReview — dispatched on successful claim + async submit
 *   5. handleDraftReviews — only processes tasks with hasOpenComments === true
 *   6. handleDraftReviews — skips all tasks when none have hasOpenComments === true
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import type { PrStatusResult } from "../src/poll/check-in-review-prs.js";
import {
  dispatchOneReview,
  handleDraftReviews,
  type DispatchOneReviewOptions,
  type HandleDraftReviewsOptions,
} from "../src/pr-response/dispatch-draft-review.js";
import { FakeBrokerAdapter } from "@workflow/runtime-abi";

// ── Mock node:child_process ───────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual =
    await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Mock SubProcessAdapterW2 (T6: async submit) ───────────────────────────────

vi.mock("../src/adapters/executor/subprocess.js", () => ({
  SubProcessAdapterW2: vi.fn().mockImplementation(() => ({
    submit: vi.fn().mockResolvedValue("fake-review-handle"),
  })),
}));

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const TASK_ID = "T4";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const GIT_AUTHOR_EMAIL = "agent@test.com";

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: "Draft Review Task",
    repo: "impl-repo",
    status: "in_review",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: {
      actor_type: "agent",
      last_updated_by: GIT_AUTHOR_EMAIL,
      last_updated_at: "2026-04-19T00:00:00Z",
    },
    pr: {
      url: "https://github.com/myorg/impl-repo/pull/42",
      status: "open",
    },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

// ── Temp directory helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTask(task: Task, featureId = FEATURE_ID): string {
  const dir = mkdtempSync(join(tmpdir(), "dispatch-draft-unit-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(
    join(tasksDir, `${task.id}.yaml`),
    yamlStringify(task),
    "utf-8",
  );
  return dir;
}

function readTaskFromDisk(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
): Task {
  return parseYaml(
    readFileSync(
      join(workspaceRoot, "docs", "features", featureId, "tasks", `${taskId}.yaml`),
      "utf-8",
    ),
  ) as Task;
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try {
      rmSync(d, { recursive: true, force: true });
    } catch {
      /* best-effort */
    }
  }
  vi.clearAllMocks();
});

// ── Mock helpers ──────────────────────────────────────────────────────────────

function mockSpawnSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0,
    output: [],
    stdout: "",
    stderr: "",
    status: 0,
    signal: null,
    error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function mockSpawnFailure(stderr = "rejected"): ReturnType<typeof spawnSync> {
  return {
    pid: 0,
    output: [],
    stdout: "",
    stderr,
    status: 1,
    signal: null,
    error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function makeDispatchOpts(
  workspaceRoot: string,
  overrides: Partial<DispatchOneReviewOptions> = {},
): DispatchOneReviewOptions {
  return {
    workspaceRoot,
    featureId: FEATURE_ID,
    taskId: TASK_ID,
    taskBranch: TASK_BRANCH,
    implRepoRoot: "/fake/impl-repo",
    implRepoUrl: "git@github.com:myorg/impl-repo.git",
    gitAuthorEmail: GIT_AUTHOR_EMAIL,
    workflowLocalPath: "/fake/workflow",
    maxTurns: 10,
    maxTokens: 100_000,
    logSinkEnabled: false,
    implementationModel: "claude-sonnet-4-6",
    workspaceId: "workspace",
    githubToken: "gh_fake_token",
    broker: new FakeBrokerAdapter(),
    callbackUrl: "http://127.0.0.1:9999/callback",
    emit: () => {},
    ...overrides,
  };
}

// ── 1. claim_lost when checkout of task branch fails ─────────────────────────

describe("dispatchOneReview — claim_lost on checkout failure", () => {
  it("returns claim_lost and emits review_claim_lost when checkout throws", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    // fetch succeeds, checkout throws
    vi.mocked(execSync).mockImplementationOnce(() => ""); // fetch
    vi.mocked(execSync).mockImplementationOnce(() => {
      throw new Error("not a git branch");
    }); // checkout

    const outcome = await dispatchOneReview(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
    expect(events.some((e) => e.type === "review_claim_lost")).toBe(true);
  });
});

// ── 2. claim_lost when last log entry is review_started ──────────────────────

describe("dispatchOneReview — claim_lost when already claimed", () => {
  it("returns claim_lost if the last log entry is review_started", async () => {
    const task = makeTask({
      log: [
        {
          action: "review_started",
          by: "other-agent@example.com",
          at: "2026-04-19T10:00:00Z",
          note: "Already claimed.",
        },
      ],
    });
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    // fetch + checkout + reset all succeed
    vi.mocked(execSync)
      .mockImplementationOnce(() => "") // fetch
      .mockImplementationOnce(() => "") // checkout
      .mockImplementationOnce(() => ""); // reset --hard

    const outcome = await dispatchOneReview(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
    expect(events.some((e) => e.type === "review_claim_lost")).toBe(true);
    const ev = events.find((e) => e.type === "review_claim_lost")!;
    expect(String(ev.details)).toMatch(/review_started/);
  });

  it("allows a new claim when review_started is not the last entry (prior round ended)", async () => {
    const task = makeTask({
      log: [
        {
          action: "review_started",
          by: "other-agent@example.com",
          at: "2026-04-19T10:00:00Z",
          note: "First review round.",
        },
        {
          action: "blocked",
          by: "other-agent@example.com",
          at: "2026-04-19T11:00:00Z",
          note: "Blocked mid-review.",
        },
      ],
    });
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    // fetch + checkout + reset + add + commit all succeed
    vi.mocked(execSync).mockImplementation(() => "");
    // push succeeds
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    const outcome = await dispatchOneReview(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("dispatched");
    expect(events.some((e) => e.type === "review_claim_lost")).toBe(false);
  });
});

// ── 2b. review_loop_detected after 3 consecutive review cycles ───────────────

describe("dispatchOneReview — review_loop_detected", () => {
  function makeReviewCycleLogs(cycles: number) {
    const log: Task["log"] = [
      { action: "in_review", by: "human@example.com", at: "2026-04-19T09:00:00Z", note: "PR opened." },
    ];
    for (let i = 0; i < cycles; i++) {
      log.push({ action: "review_started", by: "agent@example.com", at: `2026-04-19T${10 + i}:00:00Z`, note: "Claimed." });
      log.push({ action: "comments_addressed", by: "agent@example.com", at: `2026-04-19T${10 + i}:30:00Z`, note: "Addressed." });
    }
    return log;
  }

  it("returns claim_lost and emits review_loop_detected after 3 cycles", async () => {
    const task = makeTask({ log: makeReviewCycleLogs(3) });
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync)
      .mockImplementationOnce(() => "") // fetch
      .mockImplementationOnce(() => "") // checkout
      .mockImplementationOnce(() => ""); // reset --hard

    const outcome = await dispatchOneReview(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
    expect(events.some((e) => e.type === "review_loop_detected")).toBe(true);
  });

  it("dispatches when only 2 cycles have occurred (under threshold)", async () => {
    const task = makeTask({ log: makeReviewCycleLogs(2) });
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    const outcome = await dispatchOneReview(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("dispatched");
    expect(events.some((e) => e.type === "review_loop_detected")).toBe(false);
  });

  it("resets after a human non-review log entry breaks the streak", async () => {
    const task = makeTask({
      log: [
        ...makeReviewCycleLogs(3),
        { action: "in_review", by: "human@example.com", at: "2026-04-19T15:00:00Z", note: "Human reset." },
      ],
    });
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    const outcome = await dispatchOneReview(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("dispatched");
    expect(events.some((e) => e.type === "review_loop_detected")).toBe(false);
  });
});

// ── 3. claim_lost when push of claim commit is rejected ──────────────────────

describe("dispatchOneReview — claim_lost on push rejection", () => {
  it("returns claim_lost when the claim push is rejected", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    // fetch + checkout + reset + add + commit all succeed
    vi.mocked(execSync).mockImplementation(() => "");

    // push rejected
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnFailure("rejected"));

    const outcome = await dispatchOneReview(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
    expect(events.some((e) => e.type === "review_claim_lost")).toBe(true);
  });
});

// ── 4. dispatched on successful claim + async submit (T6) ────────────────────

describe("dispatchOneReview — dispatched on success (async submit)", () => {
  it("writes review_started to task YAML, pushes, submits executor, emits review_submitted", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync).mockImplementation(() => ""); // all execSync succeed
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess()); // push succeeds

    const outcome = await dispatchOneReview(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("dispatched");

    // review_started should be in the task YAML on disk
    const updatedTask = readTaskFromDisk(wsRoot, FEATURE_ID, TASK_ID);
    expect(updatedTask.log.some((e) => e.action === "review_started")).toBe(true);
    const startedEntry = updatedTask.log.find((e) => e.action === "review_started")!;
    expect(startedEntry.by).toBe(GIT_AUTHOR_EMAIL);

    // T6: emits review_dispatching + review_submitted (not review_dispatch_complete;
    // the completion event is emitted by the reap loop when runner POSTs callback)
    expect(events.some((e) => e.type === "review_dispatching")).toBe(true);
    expect(events.some((e) => e.type === "review_submitted")).toBe(true);
    const submittedEvent = events.find((e) => e.type === "review_submitted")!;
    expect(submittedEvent.task_id).toBe(TASK_ID);
    expect(submittedEvent.feature_id).toBe(FEATURE_ID);
    expect(submittedEvent.handle).toBe("fake-review-handle");

    // review_dispatch_complete is NOT emitted by dispatchOneReview in T6
    expect(events.some((e) => e.type === "review_dispatch_complete")).toBe(false);
  });
});

// ── 5. handleDraftReviews — only processes tasks with hasOpenComments ─────────

describe("handleDraftReviews — processes only tasks with open comments", () => {
  it("dispatches only tasks with hasOpenComments === true", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    const prResults: PrStatusResult[] = [
      {
        taskId: TASK_ID,
        featureId: FEATURE_ID,
        workspaceRoot: wsRoot,
        mergeable: true,
        draft: false,
        hasOpenComments: true,
      },
      {
        taskId: "T5",
        featureId: FEATURE_ID,
        workspaceRoot: wsRoot,
        mergeable: true,
        draft: false,
        hasOpenComments: false,
      },
      {
        taskId: "T6",
        featureId: FEATURE_ID,
        workspaceRoot: wsRoot,
        mergeable: null,
        draft: true,
        hasOpenComments: false,  // draft but no open comments — should NOT dispatch
      },
    ];

    // Make dispatchOneReview return claim_lost immediately to avoid deep mocking
    vi.mocked(execSync).mockImplementation(() => {
      throw new Error("forced claim lost");
    });

    const opts: HandleDraftReviewsOptions = {
      prResults,
      workspaceRoot: wsRoot,
      resolveImplRepoRoot: () => "/fake/impl",
      resolveImplRepoUrl: () => "git@github.com:myorg/impl-repo.git",
      resolveTaskRepoId: () => "impl-repo",
      resolveImplementationModel: () => "claude-sonnet-4-6",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      workflowLocalPath: "/fake/workflow",
      maxTurns: 10,
      maxTokens: 100_000,
      logSinkEnabled: false,
      workspaceId: "workspace",
      githubToken: "gh_fake_token",
      broker: new FakeBrokerAdapter(),
      callbackUrl: "http://127.0.0.1:9999/callback",
      emit: (e) => events.push(e),
    };

    await handleDraftReviews(opts);

    // Only TASK_ID (hasOpenComments: true) should have triggered a claim attempt.
    const claimLostEvents = events.filter((e) => e.type === "review_claim_lost");
    expect(claimLostEvents).toHaveLength(1);
    expect(claimLostEvents[0].task_id).toBe(TASK_ID);
  });

  it("skips all tasks when none have hasOpenComments === true", async () => {
    const wsRoot = mkdtempSync(join(tmpdir(), "handle-draft-skip-"));
    tmpDirs.push(wsRoot);
    const events: Record<string, unknown>[] = [];

    const prResults: PrStatusResult[] = [
      { taskId: "T1", featureId: "feat-x", workspaceRoot: wsRoot, mergeable: true, draft: false, hasOpenComments: false },
      { taskId: "T2", featureId: "feat-x", workspaceRoot: wsRoot, mergeable: null, draft: true, hasOpenComments: false },
    ];

    const opts: HandleDraftReviewsOptions = {
      prResults,
      workspaceRoot: wsRoot,
      resolveImplRepoRoot: () => "/fake/impl",
      resolveImplRepoUrl: () => "git@github.com:myorg/impl-repo.git",
      resolveTaskRepoId: () => "impl-repo",
      resolveImplementationModel: () => "claude-sonnet-4-6",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      workflowLocalPath: "/fake/workflow",
      maxTurns: 10,
      maxTokens: 100_000,
      logSinkEnabled: false,
      workspaceId: "workspace",
      githubToken: "gh_fake_token",
      broker: new FakeBrokerAdapter(),
      callbackUrl: "http://127.0.0.1:9999/callback",
      emit: (e) => events.push(e),
    };

    await handleDraftReviews(opts);

    expect(vi.mocked(execSync)).not.toHaveBeenCalled();
    expect(events).toHaveLength(0);
  });
});

